R=[
(r'q(r"إذا كانت السرعة $ع$ لجسيم يتحرك في خط مستقيم دالة في الزمن $ن$، فإن إزاحة الجسيم خلال الفترة الزمنية $[ن_{1} ، ن_{2}]$ تساوي"',
 r'q(r"إذا علمت السرعة $ع$ كدالة في الزمن لجسيم يتحرك في خط مستقيم، فإن التكامل الذي يعطي إزاحته من اللحظة $ن_{1}$ إلى اللحظة $ن_{2}$ هو"'),
(r'q(r"المساحة المحصورة بين منحنى (العجلة - الزمن) ومحور الزمن أعلى المحور مطروحًا منها المساحة المحصورة أسفله خلال فترة زمنية تساوي ....... خلال هذه الفترة"',
 r'q(r"إذا وقعت المساحة المحصورة بين منحنى (العجلة - الزمن) ومحور الزمن خلال فترة زمنية كلها أعلى محور الزمن، فإن هذه المساحة تمثل ....... خلال تلك الفترة"'),
(r'q(r"جسيم يتحرك في خط مستقيم بسرعة $ع = (4ن - 1)$ م/ث، فإن إزاحته خلال الفترة الزمنية $[1 ، 3]$ تساوي ....... متر"',
 r'q(r"إذا كانت سرعة جسيم يتحرك في خط مستقيم تعطى كدالة في الزمن بالعلاقة $ع = (4ن - 1)$ م/ث، فإن إزاحته من اللحظة $ن = 1$ ث حتى اللحظة $ن = 3$ ث تساوي ....... متر"'),
(r'q(r"جسيم يتحرك في خط مستقيم بسرعة $ع = (8 - 2ن)$ سم/ث، فإن إزاحته خلال الفترة الزمنية $[2 ، 7]$ تساوي ....... سم"',
 r'q(r"ما القياس الجبري لإزاحة جسيم بين اللحظتين $ن = 2$ ث و$ن = 7$ ث إذا كان يتحرك على خط مستقيم وسرعته عند أي لحظة $ع = (8 - 2ن)$ سم/ث؟"'),
(r'q(r"جسيم يتحرك في خط مستقيم بعجلة $ح = 32 هـ^{-س}$ م/ث$^{2}$، وبدأ حركته من نقطة الأصل بسرعة $6$ م/ث، فإن $ع^{2}$ بدلالة $س$ تعطى بالعلاقة"',
 r'q(r"يتحرك جسيم في خط مستقيم من نقطة الأصل بسرعة ابتدائية $6$ م/ث، وعجلته عند أي موضع $س$ تساوي $32 هـ^{-س}$ م/ث$^{2}$. أي العلاقات الآتية تربط مربع سرعته بموضعه؟"'),
(r'q(r"جسيم يتحرك في خط مستقيم بعجلة $ح = 3س^{2}$ م/ث$^{2}$، وبدأ حركته من نقطة الأصل بسرعة $2$ م/ث، فإن سرعته عندما $س = 2$ متر تساوي ....... م/ث"',
 r'q(r"إذا كان القياس الجبري لعجلة جسيم يتحرك في خط مستقيم يعطى بدلالة موضعه بالعلاقة $ح = 3س^{2}$، وكان الجسيم قد مر بنقطة الأصل بسرعة $2$ م/ث، فما سرعته بوحدة م/ث لحظة وصوله إلى الموضع $س = 2$ متر؟"'),
(r'q(r"بدأ جسيم حركته من السكون في خط مستقيم بعجلة $ح = (12 - 3ن^{2})$ م/ث$^{2}$، فإن أقصى سرعة يبلغها الجسيم تساوي ....... م/ث"',
 r'q(r"تعطى عجلة سيارة بدأت حركتها من السكون على طريق مستقيم بالعلاقة $ح = (12 - 3ن^{2})$ م/ث$^{2}$، فما السرعة العظمى التي تصل إليها السيارة بوحدة م/ث؟"'),
(r'q(r"جسيم يتحرك في خط مستقيم بسرعة $ع = (3ن^{2} - 12ن)$ م/ث، فإن المسافة الكلية التي يقطعها خلال الفترة الزمنية $[0 ، 5]$ تساوي ....... متر"',
 r'q(r"إذا كانت سرعة جسيم بعد $ن$ ثانية من بدء حركته في خط مستقيم هي $ع = (3ن^{2} - 12ن)$ م/ث، فإن المسافة الكلية التي يقطعها في الثواني الخمس الأولى من حركته تساوي ....... متر"'),
(r'q(r"جسيم يتحرك في خط مستقيم بسرعة $ع = (ن^{2} - 4ن + 3)$ م/ث، فإن المسافة الكلية التي يقطعها خلال الفترة الزمنية $[0 ، 3]$ تساوي ....... متر"',
 r'q(r"يتحرك جسيم على خط مستقيم بحيث $ع = (ن^{2} - 4ن + 3)$ م/ث، فإن مجموع المسافات التي يقطعها منذ بدء الحركة حتى نهاية الثانية الثالثة يساوي ....... متر"'),
(r'q(r"جسيم يتحرك في خط مستقيم بسرعة $ع = (ن^{2} - 4ن)$ م/ث، فإن القياس الجبري لمتجه السرعة المتوسطة خلال الفترة الزمنية $[0 ، 6]$ يساوي ....... م/ث"',
 r'q(r"تتحرك نقطة مادية في خط مستقيم بحيث $ع = (ن^{2} - 4ن)$ م/ث، فما القياس الجبري لمتجه سرعتها المتوسطة بوحدة م/ث خلال الثواني الست الأولى من الحركة؟"'),
(r'q(r"جسيم يتحرك في خط مستقيم بسرعة $ع = (12 - 3ن)$ سم/ث، فإن السرعة المتوسطة (المسافة الكلية مقسومة على الزمن) خلال الفترة الزمنية $[0 ، 6]$ تساوي ....... سم/ث"',
 r'q(r"ما السرعة المتوسطة بوحدة سم/ث لجسيم سرعته $ع = (12 - 3ن)$ سم/ث خلال الثواني الست الأولى من حركته، علمًا بأن السرعة المتوسطة هي المسافة الكلية مقسومة على الزمن؟"'),
(r'q(r"بدأ جسيم حركته من السكون في خط مستقيم، وكان منحنى (العجلة - الزمن) له قطعة مستقيمة تبدأ من النقطة $(0 ، 0)$ وتنتهي عند النقطة $(4 ، 8)$ حيث العجلة بوحدة م/ث$^{2}$ والزمن بالثانية، فإن إزاحة الجسيم خلال الفترة $[0 ، 4]$ تساوي ....... متر"',
 r'q(r"منحنى (العجلة - الزمن) لجسيم بدأ حركته من السكون هو قطعة مستقيمة تصل بين نقطة الأصل والنقطة $(4 ، 8)$، حيث الزمن بالثانية والعجلة بوحدة م/ث$^{2}$. ما إزاحة الجسيم بالمتر في الثواني الأربع الأولى؟"'),
(r'q(r"منحنى (السرعة - الزمن) لجسيم يتحرك في خط مستقيم يتكون من قطعة مستقيمة من النقطة $(0 ، 0)$ إلى النقطة $(2 ، 6)$، ثم قطعة مستقيمة من $(2 ، 6)$ إلى $(6 ، -6)$، ثم قطعة أفقية من $(6 ، -6)$ إلى $(8 ، -6)$، ثم قطعة مستقيمة من $(8 ، -6)$ إلى $(10 ، 0)$ حيث السرعة بوحدة م/ث والزمن بالثانية، فإن المسافة الكلية التي قطعها الجسيم خلال الفترة $[0 ، 10]$ تساوي ....... متر"',
 r'q(r"يتحرك جسيم في خط مستقيم بحيث تزداد سرعته بانتظام من $0$ إلى $6$ م/ث خلال أول ثانيتين، ثم تتغير بانتظام حتى تصبح $-6$ م/ث عند $ن = 6$ ث، ثم تبقى $-6$ م/ث حتى $ن = 8$ ث، ثم تتغير بانتظام حتى يسكن الجسيم عند $ن = 10$ ث. ما المسافة الكلية بالمتر التي قطعها الجسيم خلال هذه الثواني العشر؟"'),
]
